namespace Gordic.Pok.WebClient {

    @Decorators.gcontent
    export class GPokSablonyZkratkyTab extends GContentBase {

     
        title: string;
        editMode: boolean;
        ixsPitSeznam: string;
        panelItems: Gordic.Hpl.Interface.GPokvzktDto[];
        newTask: boolean;
     
        onContentReady() {

            var that = this;

            that.actions.addRange({
                actSmazat:
                {
                    caption: "Vymazat všechny zkratky",
                    icon: Gordic.Gin.Icons.ActionEnum.odstranit,
                    visible: that.editMode,
                    run: function (ev, ctx) {

                        that.isl.PokSablona.vymazatZkratky()
                            .get()
                            .done(function () {
                                that.tryClose().done(function () {                              
                                    Gordic.Pok.WebClient.GPokFlash.showFlashSuccess(that.parentContent!, "Všechny zkratky byly smazány!");

                                })
                            })
                            .fail(function (xhr, type, vobj) {
                                if (type === "exception") {
                                    if (vobj.baseType === "Gordic.General.GHplValidationException") {
                                        vobj.handled = true;                                    
                                        Gordic.Pok.WebClient.GPokFlash.showFlashError(that, vobj.baseMessage);

                                    }
                                }
                            })
                    }
                }
            });

            if (this.editMode)
                that.menuBar(that.actions.createBar(["actSmazat*"]));


            let someShortCut = [7, 8, 9, 4, 5, 6, 1, 2, 3];

            

            someShortCut.forEach(function (row) {

                that.element.gshortcut({
                    key: row.toString(),
                    action: new GAction({ name: "actClick" + row.toString(), run: () => { that.akceKlik(row); } }),
                    description: "Použití šablony " + row.toString(),
                    group: Gordic.Shortcuts.Groups.Task
                });
            });

            that.isl.PokSablona.listZkratky(rq => { return {} })
                .get()
                .done(function (data) {

                    that.panelItems = data.data;

                    let nazev1 = data.data.find(function (element) { return element.zkratka == 1 });
                    let nazev2 = data.data.find(function (element) { return element.zkratka == 2 });
                    let nazev3 = data.data.find(function (element) { return element.zkratka == 3 });
                    let nazev4 = data.data.find(function (element) { return element.zkratka == 4 });
                    let nazev5 = data.data.find(function (element) { return element.zkratka == 5 });
                    let nazev6 = data.data.find(function (element) { return element.zkratka == 6 });
                    let nazev7 = data.data.find(function (element) { return element.zkratka == 7 });
                    let nazev8 = data.data.find(function (element) { return element.zkratka == 8 });
                    let nazev9 = data.data.find(function (element) { return element.zkratka == 9 });                                 

                    let test = $("<div class=\"pokZkratkyContainer\"></div>").appendTo(that.element);
                    let row1 = $("<div class=\"pokZkratkyRow\"></div>").appendTo(test);
                    $("<div class=\"pokZkratkyCell\"><h2>1</h2><h3>" + (nazev1 ? nazev1.nazev_sablony : "") + "</h3></div>").on("click", (ev) => {
                        that.akceKlik(1);
                    }).appendTo(row1);
                    $("<div class=\"pokZkratkyCell\"><h2>2</h2><h3>" + (nazev2 ? nazev2.nazev_sablony : "") + "</h3></div>").on("click", (ev) => {
                        that.akceKlik(2);
                    }).appendTo(row1);
                    $("<div class=\"pokZkratkyCell\"><h2>3</h2><h3>" + (nazev3 ? nazev3.nazev_sablony : "") + "</h3></div>").on("click", (ev) => {
                        that.akceKlik(3);
                    }).appendTo(row1);
                    let row2 = $("<div class=\"pokZkratkyRow\"></div>").appendTo(test);
                    $("<div class=\"pokZkratkyCell\"><h2>4</h2><h3>" + (nazev4 ? nazev4.nazev_sablony : "") + "</h3></div>").on("click", (ev) => {
                        that.akceKlik(4);
                    }).appendTo(row2);
                    $("<div class=\"pokZkratkyCell\"><h2>5</h2><h3>" + (nazev5 ? nazev5.nazev_sablony : "") + "</h3></div>").on("click", (ev) => {
                        that.akceKlik(5);
                    }).appendTo(row2);
                    $("<div class=\"pokZkratkyCell\"><h2>6</h2><h3>" + (nazev6 ? nazev6.nazev_sablony : "") + "</h3></div>").on("click", (ev) => {
                        that.akceKlik(6);
                    }).appendTo(row2);
                    let row3 = $("<div class=\"pokZkratkyRow\"></div>").appendTo(test);
                    $("<div class=\"pokZkratkyCell\"><h2>7</h2><h3>" + (nazev7 ? nazev7.nazev_sablony : "") + "</h3></div>").on("click", (ev) => {
                        that.akceKlik(7);
                    }).appendTo(row3);
                    $("<div class=\"pokZkratkyCell\"><h2>8</h2><h3>" + (nazev8 ? nazev8.nazev_sablony : "") + "</h3></div>").on("click", (ev) => {
                        that.akceKlik(8);
                    }).appendTo(row3);
                    $("<div class=\"pokZkratkyCell\"><h2>9</h2><h3>" + (nazev9 ? nazev9.nazev_sablony : "") + "</h3></div>").on("click", (ev) => {
                        that.akceKlik(9);
                    }).appendTo(row3);
                  

                            
                });
        }
        
        private akceKlik(cislo : number): void {

            let that = this;

            if (that.editMode) // uložení nové zkratky
            {

                that.isl.PokSablona.nastavitZkratku(rq => {
                    return {
                        ixsPit: that.ixsPitSeznam,
                        zkratka: cislo!
                    }
                })
                    .get()
                    .done(function (text) {
                        that.tryClose().done(function () {                          
                            Gordic.Pok.WebClient.GPokFlash.showFlashSuccess(that.parentContent!, "Zkratka byla uložena!");

                        })
                    })
                    .fail(function (xhr, type, vobj) {
                        if (type === "exception") {
                            if (vobj.baseType === "Gordic.General.GHplValidationException") {
                                vobj.handled = true;
                                Gordic.Pok.WebClient.GPokFlash.showFlashError(that, vobj.baseMessage);
                            }
                        }
                    })

            }
            else { //podání pokladního dokladu


                let vybranaZkratka = that.panelItems.find(function (element) { return element.zkratka == cislo })

                if (!vybranaZkratka)
                    return;

                Gordic.Pok.WebClient.GPokWebDoklad.promisePodaniSablona(that, true, vybranaZkratka.ixs_pit!)
                    .done(function (ixp: string) {

                        that.tryClose().done(function () {

                            if (that.newTask) {

                                that.parentContent!.
                                        navigate("Gordic.Pok.WebClient.GPokDetailDokladuTab", {
                                        ixp: ixp,
                                        newPodani: true
                                    });

                            } else {
                                that.parentContent!.
                                    load({
                                        ixp: ixp,
                                        newPodani: true 
                                    });
                            }

                           
                        })
                    })
                    .fail(function (zprava: string) {
                        if (zprava)
                            Gordic.Pok.WebClient.GPokFlash.showFlashWarning(that, zprava);
                    });
            }
        }

    }

}